export function schoolSyllabusSeed(id: number) {
  return seeds[id];
}

export function schoolSyllabusLesson(seed: SchoolSyllabusSeed): StrengthenedLesson {
  const slug = seed.route.split("/").pop() ?? String(seed.id);
  const code = seed.misconception[0];
  return {
    id: seed.id,
    title: seed.title,
    route: seed.route,
    category: "School Syllabus",
    topic: seed.topic,
    academicLevel: seed.academicLevel,
    lessonType: seed.lessonType,
    learningObjectives: [`Define ${seed.title} correctly.`, seed.action, `Avoid this mistake: ${seed.misconception[1]}`],
    prerequisites: prerequisitesFor(seed.topic),
    keyVocabulary: [{ term: seed.title, meaning: seed.definition }, vocabularyFor(seed.topic)],
    introduction: `${seed.title} is a school mathematics idea in ${seed.topic}. It helps learners solve classwork and daily problems with a clear rule. We use it in measurements, data, patterns, geometry, and algebra decisions.`,
    basicIdea: `${seed.definition} The basic idea is to identify the correct rule before calculating or drawing. ${seed.reason} A common mistake is ${seed.misconception[1]}`,
    howItWorks: `${seed.action} Then check the answer against the condition in the question.`,
    whyItWorks: whyFor(seed.topic),
    definitions: [{ id: `${slug}-definition`, statement: seed.definition }],
    facts: [{ id: `${slug}-fact`, statement: seed.reason }],
    formulas: seed.formula ? [seed.formula] : [],
    conditionsAndRestrictions: restrictionsFor(seed.topic),
    representations: [{ id: `${slug}-representation`, type: seed.representation, learningPurpose: `Show the exact structure of ${seed.title}.` }],
    workedExamples: [{ id: `${slug}-worked-1`, prompt: seed.prompt, steps: ["Read the given information.", seed.action, "Check the result against the lesson rule."], answer: seed.expected }],
    realLifeExamples: seed.examples.map(([context, connection], index) => ({ id: `${slug}-real-${index + 1}`, context, connection })),
    misconceptions: [{ code, mistake: seed.misconception[1], correction: seed.misconception[2] }],
    interaction: {
      id: `${slug}-interaction`,
      learningPurpose: `Explore ${seed.title} with a linked school-style model.`,
      parameters: [{ id: "value", label: "Value", validRange: [1, 20] }],
      initialState: `Start with the worked example for ${seed.title}.`,
      dynamicFeedback: "Changing one input updates the model, table, graph, construction, or proof check.",
      successCriteria: ["Use the correct rule", "Read the representation", "Explain the common mistake"],
      accessibilityAlternative: "Provide the same steps and result as labelled text.",
    },
    guidedExploration: [{ id: "predict", prompt: "Predict the result before changing the model." }, { id: "test", prompt: "Change one input and read the new result." }, { id: "explain", prompt: "Explain why the rule still works." }],
    practice: [
      practice(`${slug}-recognition`, `What is ${seed.title}?`, seed.definition, code, "recognition"),
      practice(`${slug}-direct`, seed.prompt, seed.expected, code, "direct"),
      practice(`${slug}-multi`, `How do you use ${seed.title}?`, seed.action, code, "multi_step"),
      practice(`${slug}-error`, `What is wrong with this mistake: ${seed.misconception[1]}`, seed.misconception[2], code, "error_diagnosis"),
      practice(`${slug}-transfer`, `Give one daily use of ${seed.title}.`, seed.examples[0][0], code, "transfer"),
    ],
    challenge: { id: `${slug}-challenge`, prompt: seed.prompt, successCriteria: ["Uses the exact rule", "Checks conditions", "Avoids the named mistake"], hints: [`Use the rule for ${seed.title}.`, seed.misconception[2]] },
    exitCheck: [{ id: `${slug}-exit`, prompt: `State one rule for ${seed.title}.`, answer: seed.misconception[2], criterion: "Answer names a correct rule or condition." }],
    accessibilityNotes: ["Announce values, labels, and construction steps as text.", "Do not rely only on colour."],
    expertReviewRequired: Boolean(seed.expertReviewRequired),
    reviewReason: seed.expertReviewRequired ? "This theorem or proof-heavy school lesson needs expert review." : undefined,
  };
}

function seed(id: number, title: string, route: string, topic: string, academicLevel: string, lessonType: SchoolSyllabusSeed["lessonType"], definition: string, action: string, reason: string, representation: SchoolSyllabusSeed["representation"], misconception: SchoolSyllabusSeed["misconception"], examples: SchoolSyllabusSeed["examples"], prompt: string, expected: string, formula?: SchoolSyllabusSeed["formula"], expertReviewRequired?: boolean): SchoolSyllabusSeed {
  return { id, title, route, topic, academicLevel, lessonType, definition, action, reason, representation, misconception, examples, prompt, expected, formula, expertReviewRequired };
}

function formula(label: string, expression: string, variables: [string, string][], exactness: NonNullable<SchoolSyllabusSeed["formula"]>["exactness"]): NonNullable<SchoolSyllabusSeed["formula"]> {
  return { id: `${label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-formula`, label, expression, variables: variables.map(([symbol, meaning]) => ({ symbol, meaning })), exactness };
}

export function schoolSyllabusChallenge(seed: SchoolSyllabusSeed): SchoolSyllabusBatchChallenge {
  return {
    prompt: seed.prompt,
    expected: seed.expected,
    hint: `Use the rule for ${seed.title}.`,
    kind: Number.isFinite(Number(seed.expected)) ? "numeric" : "keywords",
    factoryId: `school.${seed.id}`,
  };
}

function vocabularyFor(topic: string) {
  if (/Geometry/.test(topic)) return { term: "Construction", meaning: "An exact drawing made from allowed geometric steps." };
  if (/Data/.test(topic)) return { term: "Data", meaning: "Information collected to answer a question." };
  if (/Polynomial/.test(topic)) return { term: "Polynomial", meaning: "An expression made from powers of a variable with coefficients." };
  if (/Real Numbers/.test(topic)) return { term: "Real number", meaning: "A number that can be placed on the number line." };
  return { term: "Rule", meaning: "A clear step that decides what to do next." };
}

function prerequisitesFor(topic: string) {
  if (/Geometry/.test(topic)) return ["Points and lines", "Angles", "Using ruler and compass"];
  if (/Data/.test(topic)) return ["Counting", "Tables", "Reading labels"];
  if (/Polynomial/.test(topic)) return ["Variables", "Exponents", "Substitution"];
  if (/Real Numbers/.test(topic)) return ["Fractions", "Decimals", "Number-line order"];
  return ["Whole numbers", "Basic operations", "Reading the question carefully"];
}

function restrictionsFor(topic: string) {
  if (/Geometry/.test(topic)) return ["Use only the stated construction tools.", "Do not assume a diagram is exact unless constructed."];
  if (/Data/.test(topic)) return ["Label axes or symbols clearly.", "Use the same scale for fair comparison."];
  if (/Polynomial/.test(topic)) return ["Keep terms in like powers.", "Check substitutions exactly."];
  if (/Real Numbers/.test(topic)) return ["Check whether the decimal terminates or repeats.", "Use exact radical rules when needed."];
  return ["Keep units consistent.", "Check the operation and the base quantity."];
}

function whyFor(topic: string) {
  if (/Geometry/.test(topic)) return "Geometry works because exact conditions force fixed relationships between points, lines, angles, and shapes.";
  if (/Data/.test(topic)) return "Data handling works because organised counts and scales make information easier to compare.";
  if (/Polynomial/.test(topic)) return "Polynomial rules work because substitution, division, and factorisation follow the structure of powers.";
  if (/Real Numbers/.test(topic)) return "Real-number rules work because every real number has a fixed position on the number line.";
  return "The method works because each step preserves the value, unit, or pattern stated in the problem.";
}

function practice(id: string, prompt: string, answer: string, misconceptionTag: string, difficulty: StrengthenedLesson["practice"][number]["difficulty"]): StrengthenedLesson["practice"][number] {
  return { id, prompt, answer, hints: ["Read the condition.", "Choose the matching rule.", "Check the final answer."], workedSolution: ["Identify the given information.", "Apply the lesson rule.", "Check the answer in context."], misconceptionTag, difficulty, parameterConstraints: ["Use school-level whole numbers, simple measurements, or exact algebraic values."] };
}
